WITH owned AS(SELECT unnest(ARRAY['97d2a684-956d-57ad-8d84-aca627dd9e5c','e5aa6156-c725-5e99-b4f3-b798977affd5']::uuid[]) sid), scene AS(SELECT o.sid,m.stato,m.closed_at,m.control_version master_cv,q.state,q.control_version quest_cv,q.episode_id,q.episode_ordinal,q.prepare_request_key,q.start_request_key,q.terminal_receipt_id,q.source_sha256,q.roster_snapshot_sha256,r.run_phase,r.control_version run_cv FROM owned o JOIN public.master_v2_sessions m ON m.id=o.sid JOIN mission_factory_owner.quest_run_sources q ON q.session_id=o.sid JOIN public.mission_run_state r ON r.master_session_id=o.sid), term AS(SELECT o.sid,count(t.id) receipt_count,count(p.id) publication_count,bool_and(t.publication_id=p.id AND t.close_event_id=p.event_id) publication_binding_exact,max(t.created_at) terminal_at,jsonb_agg(jsonb_build_object('receipt_id',t.id,'publication_id',t.publication_id,'request_key',t.request_key,'close_event_id',t.close_event_id,'receipt_sha256',mission_factory_owner.sha(t.receipt),'outcome',t.outcome)) receipts FROM owned o LEFT JOIN mission_factory_owner.quest_terminal_receipts t ON t.session_id=o.sid LEFT JOIN public.mission_run_publications p ON p.id=t.publication_id GROUP BY o.sid) SELECT jsonb_build_object('at',clock_timestamp(),'scenes',(SELECT jsonb_agg(to_jsonb(s) ORDER BY episode_ordinal) FROM scene s),'both_terminal',(SELECT count(*)=2 AND bool_and(stato='chiusa' AND closed_at IS NOT NULL AND state='terminal') FROM scene),'terminal_receipts',(SELECT jsonb_agg(to_jsonb(t) ORDER BY sid) FROM term t),'terminal_unique',(SELECT count(*)=2 AND bool_and(receipt_count=1 AND publication_count=1 AND publication_binding_exact) FROM term),'own_open_sessions',(SELECT count(*) FROM public.master_v2_sessions m WHERE m.id IN(SELECT sid FROM owned) AND closed_at IS NULL),'own_actor_other_open_sessions',(SELECT count(DISTINCT m.id) FROM public.master_v2_participants p JOIN public.master_v2_sessions m ON m.id=p.session_id WHERE p.character_id=ANY(ARRAY['6bceee99-974f-426b-8d92-38b43b4a4267','f335b077-34a1-41c3-94aa-58ec674b649b']::uuid[]) AND m.closed_at IS NULL),'participants',(SELECT jsonb_agg(x ORDER BY x->>'session_id') FROM(SELECT jsonb_build_object('session_id',session_id,'count',count(*),'all_concluso',bool_and(engagement_state='concluso' AND left_at IS NOT NULL),'md5',md5(jsonb_agg(to_jsonb(p) ORDER BY character_id)::text)) x FROM public.master_v2_participants p WHERE session_id IN(SELECT sid FROM owned) GROUP BY session_id)t),'combat',(SELECT jsonb_agg(jsonb_build_object('id',id,'state',state,'closed_at',closed_at)) FROM public.combat_v2_sessions WHERE id='d5510d61-54d2-4a55-885e-5b534b42fbab'::uuid),'c463',(SELECT to_jsonb(x) FROM mission_factory_owner.c463_optin_control x WHERE singleton),'public_gate',(SELECT to_jsonb(x) FROM mission_public_owner.public_authoring_gate_v1 x WHERE singleton),'fixed30_gate',(SELECT to_jsonb(x) FROM mission_factory_owner.quest_fixed30_admission x WHERE singleton),'protected',(WITH targets(label,character_id) AS (VALUES ('pg_tamako','f335b077-34a1-41c3-94aa-58ec674b649b'::uuid),('master_riuji','6bceee99-974f-426b-8d92-38b43b4a4267'::uuid)), resources AS (select t.label,c.rank,c.vita,c.vita_max,c.chakra,c.chakra_max,c.exp,c.xp_lifetime,c.money,c.pool_concesso,c.unspent_points,md5(jsonb_build_array(c.taijutsu,c.ninjutsu,c.genjutsu,c.forza,c.velocita,c.mente,c.resistenza,c.fuuinjutsu,c.kekkei_genkai,c.lealta,c.via,c.fama,c.slot_extra)::text) stats_md5,(select count(*) from public.character_inventory x where x.character_id=c.id) inventory_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.item_id,x.quantity,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_inventory x where x.character_id=c.id) inventory_md5,(select count(*) from public.lesson_progress x where x.user_id=c.user_id) lesson_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.lesson_id,x.completed_at) order by x.id),'[]'::jsonb)::text) from public.lesson_progress x where x.user_id=c.user_id) lesson_md5,(select count(*) from public.character_jutsu x where x.user_id=c.user_id) jutsu_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.jutsu_id,x.source,x.learned_at) order by x.id),'[]'::jsonb)::text) from public.character_jutsu x where x.user_id=c.user_id) jutsu_md5,(select count(*) from public.character_abilities x where x.character_id=c.id) ability_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.technique_id,x.state,x.sessions_done,x.started_at,x.activated_at) order by x.id),'[]'::jsonb)::text) from public.character_abilities x where x.character_id=c.id) ability_md5,(select count(*) from public.character_perks x where x.character_id=c.id) perk_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.tipo,x.dettaglio,x.costo,x.grado_tecnica,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_perks x where x.character_id=c.id) perk_md5,(select count(*) from public.esame_prove x where x.candidate_user=c.user_id and x.stato='aperta') legacy_exam_open,(select count(*) from exam_regia_private.bindings x where x.owner_user=c.user_id and x.state<>'closed') legacy_binding_open,md5(jsonb_build_array(c.clan,c.element,c.element2,c.cercoterio,c.sigillo)::text) identity_build_md5 from targets t join public.characters c on c.id=t.character_id order by t.label) select jsonb_build_object('at',clock_timestamp(),'protected_md5',md5(jsonb_agg(to_jsonb(r) order by label)::text),'rows',count(*),'fields_per_pg',(select count(*) from jsonb_object_keys((select to_jsonb(x)-'label' from resources x limit 1)))) from resources r));